import logging
import time

from ute_ue.config import loggers as ta_ue_logging
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments, DataTransferVerificationFailure

from taf.ue.android.data_transfer.iperf.data_transfer import AndroidUeDtConfigPacker
from taf.ue.android.exceptions import DataTransferException


class AndroidDataTransferFtp(LteDataTransfer):
    """Object responsible for managing Android data transfer."""

    # pylint: disable = protected-access, too-many-instance-attributes, duplicate-code
    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """
        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param ue_instance:
        """
        super().__init__(name, dt_definition, configuration, logger_name)
        raw_logger = logging.getLogger('ute_ue')
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        self.ue_instance = ue_instance
        self.success_started = False
        self._is_running = False
        self._results = None
        self.is_direction_downlink = self._dt_definition.direction == 'ul'
        self.dt_config = FtpDtConfigPacker(dt_definition, configuration, self.logger).get_config()
        self.logger.debug(f"{self.name} created with configuration: {self.dt_config}")

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        self.logger.debug(f'{self.name} call: start data transfer')
        self.ue_instance.rpc_client.start_data_transfer(ue_id=self.ue_instance.ue_id,
                                                        data_transfer_id=self.name,
                                                        data_transfer_class="AndroidFtp",
                                                        data_transfer_config=self.dt_config)
        self.logger.debug(f"{self.name}: ftp data transfer successfully started!")
        self.success_started = True
        self._is_running = True

    def get_average_throughput(self, **kwargs):
        """
        Get average throughput of FTP data transfer
        :return:
        """
        self.logger.debug(f'{self.name} call: get average throughput')
        self._update_and_return_ftp_results()
        self.logger.debug(f"{self.name}: average_throughput = {self._results['avg_throughput']}")
        return self._results['avg_throughput']

    def get_data_transfer_statistics(self, **kwargs):
        self.logger.debug(f'{self.name} call: get data transfer statistics')
        self._update_and_return_ftp_results()
        self.logger.debug(f"{self.name}: stats = {self._results}")
        return self._results

    def await_finish(self):
        self.logger.debug(f'{self.name} call: await finish')
        if self.get_definition().is_forever_duration():
            raise DataTransferException("Can not await forever."
                                        f"\nPlease set finite duration for {self.name} data transfer")
        self.logger.debug(f"{self.name}: awaiting FTP data transfer finish for {self.dt_config['duration']}s")
        end_time = time.time() + self.dt_config['duration']
        while time.time() < end_time:
            if not self.is_running():
                self._update_and_return_ftp_results()
                self.logger.debug(f"{self.name}: dt finished, exiting loop.")
                return
            time.sleep(2)
        raise TimeoutError(f'FTP data transfer {self.name} did not finished in {self.dt_config["duration"]} seconds.')

    def is_running(self):
        if self._is_running:
            dt_current_state = self.ue_instance.rpc_client.get_data_transfer_state(ue_id=self.ue_instance.ue_id,
                                                                                   data_transfer_id=self.name)
            self.logger.debug(f"{self.name} current state: {dt_current_state}")
            self._is_running = dt_current_state == "started"
        return self._is_running

    def release_data_transfer(self):
        """Nothing to release"""
        pass

    def stop(self):
        raise NotImplementedError("There is no option to stop FTP transfer from NAA. "
                                  "Please, contact the development team if you need such possibility.")

    def check_data_transfer(self):
        raise NotImplementedError

    def reset_statistics(self):
        raise NotImplementedError

    def get_datagram_loss(self):
        raise NotImplementedError("Datagram loss not available for FTP data transfers")

    def _update_and_return_ftp_results(self):
        if not self._results:
            self.logger.debug(f'{self.name}: updating FTP results')
            self._results = self.ue_instance.rpc_client.get_data_transfer_output(ue_id=self.ue_instance.ue_id,
                                                                                 data_transfer_id=self.name,
                                                                                 raw_output=True)['raw_output']
            self.logger.debug(f'{self.name}: FTP results from UE {self.ue_instance.ue_id} = {self._results}')
            if self._results['status'] != 'success':
                raise DataTransferVerificationFailure("Something went wrong during ftp data transfer. "
                                                      "Please check if all parameters provided correctly "
                                                      "and transfer between client and server works well manually")
        return self._results


class FtpDtConfigPacker(AndroidUeDtConfigPacker):

    def __init__(self, dt_definition, yaml_config, logger):
        """Object for packing data transfer config into one dict"""
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})
        super().__init__(dt_definition, yaml_config, logger)

    def _pack_dt_keys(self, configuration):
        ftp_config = {
            'address': self.dt_definition.protocol_details.get(
                'address', self.dt_config_to_uepc['app_server'].get('address')),
            'user': self.dt_definition.protocol_details.get(
                'user', self.dt_config_to_uepc['app_server'].get('user', 'anonymous')),
            'password': self.dt_definition.protocol_details.get(
                'password', self.dt_config_to_uepc['app_server'].get('password', 'anonymous')),
            'direction': self.dt_definition.direction,
            'duration': self.dt_definition.duration
        }
        if ftp_config['address'] is None:
            raise DataTransferMissingArguments(
                "Missing FTP server address.\n"
                "Please, update your robot keyword arguments or yaml config and try again.")

        dt_mandatory_direction_args = {'dl': ['remote_path'],
                                       'ul': ['remote_path', 'file_size', 'test_index']}
        for key in dt_mandatory_direction_args[self.dt_definition.direction]:
            try:
                ftp_config[key] = self.dt_definition.protocol_details[key]
            except KeyError:
                raise DataTransferMissingArguments(
                    f"Missing `{key}` mandatory argument for {self.dt_definition.direction} FTP data transfer.\n"
                    "Please, update your robot keyword arguments and try again.\n"
                    f"Required arguments for {self.dt_definition.direction}: "
                    f"{dt_mandatory_direction_args[self.dt_definition.direction]}")
        self.dt_config_to_uepc = ftp_config

    @staticmethod
    def _get_app_server_from_yml(yaml_config):
        return yaml_config['data_transfer']['ftp']['app_server']
